async function n(){try{const s="koalastuff_github_repos";let o=null,d=null;try{d=localStorage.getItem(s)}catch{}if(d){const t=JSON.parse(d);Date.now()-t.timestamp<360*60*1e3&&(o=t.data)}if(!o){const t=await fetch("https://api.github.com/users/Shik3i/repos?sort=updated&per_page=100");if(!t.ok)return;o=await t.json();try{localStorage.setItem(s,JSON.stringify({timestamp:Date.now(),data:o}))}catch{}}const r=new Map;o.forEach(t=>{r.set(t.full_name.toLowerCase(),new Date(t.pushed_at||t.updated_at))}),document.querySelectorAll(".github-last-updated").forEach(t=>{const c=t.getAttribute("data-github-repo");if(!c)return;const i=r.get(c.toLowerCase());if(i){const e=Math.floor((Date.now()-i.getTime())/864e5);let a="";e===0?a="Updated today":e===1?a="Updated yesterday":e<30?a=`Updated ${e}d ago`:e<365?a=`Updated ${Math.floor(e/30)}mo ago`:a=`Updated ${Math.floor(e/365)}y ago`,t.innerHTML=`<span class="update-dot"></span>${a}`,t.classList.add("has-fresh-data")}})}catch(s){console.error("Failed to fetch github data",s)}}document.addEventListener("astro:page-load",n);
